mapper.select:
SELECT
    B.BOK_DETAIL_ID as bokDetailId,
    B.BASE_SUBJECT_NATURE as baseSubjectNature,
    B.HAPPEN_DATE as happenDate,
    SUM(if(B.CD_FLAG=#{cdFlag},B.O_HAPPEN_AMT,B.O_HAPPEN_AMT*(-1))) AS oHappenAmt
FROM BOK_BOOKDETAIL_CURRENT B  
INNER JOIN (
SELECT
TEMP.HAPPEN_DATE,
TEMP.BOOKSET_DATE,
TEMP.BOOK_DATE,
TEMP.BOOK_ID,
TEMP.BOOKSET_ID,
TEMP.OFFSET_FLAG
FROM (
SELECT
A.HAPPEN_DATE,
A.BOOKSET_DATE,
A.BOOK_DATE,
A.BOOK_ID,
A.BOOKSET_ID,
A.OFFSET_FLAG,
A.RN
FROM (
SELECT tmp.*,
@rownum := @rownum + 1 rownum, /* 虚拟列行标 */
IF(
(
@BOOKSET_ID = tmp.BOOKSET_ID
and @BOOK_ID = tmp.BOOK_ID
), @rank := @rank + 1, @rank := 1) AS rn, /* 分组虚拟列行标 */
@BOOKSET_ID := tmp.BOOKSET_ID /* 分组条件1 */
, @BOOK_ID := tmp.BOOK_ID /* 分组条件1 */
FROM (
/* 数据源 */
SELECT * FROM BOK_BOOKDETAIL_CURRENT ORDER BY BOOK_ORDER desc
) tmp,
/* 定义临时变量池 */
(SELECT @rownum := 0,
@BOOKSET_ID := null,
@BOOK_ID := null,
@rank := 0) a
) A
where
A.BOOKSET_ID = #{booksetId}
AND A.BOOK_DATE <= #{bookDate}

    AND A.TABLE_ID in

        #{tableId}



    AND A.TRADE_ID = #{tradeId}


    AND A.HAPPEN_DATE = #{happenDate}

) TEMP
WHERE
TEMP.RN = 1
AND TEMP.OFFSET_FLAG = #{offsetFlag}
) C
    ON C.HAPPEN_DATE = B.HAPPEN_DATE
    AND C.BOOKSET_DATE = B.BOOKSET_DATE
    AND C.BOOK_DATE = B.BOOK_DATE
    AND C.BOOK_ID = B.BOOK_ID
    AND C.BOOKSET_ID = B.BOOKSET_ID  
WHERE 1=1
    AND B.BASE_SUBJECT_NATURE = #{baseSubjectNature}
    AND B.BOK_DETAIL_ID = #{bokDetailId}
GROUP BY B.BOK_DETAIL_ID,
         B.BASE_SUBJECT_NATURE,
         B.HAPPEN_DATE
